code.java:
public boolean checkInclusion(String s1, String s2) {
    int len = s1.length();
    if (len > s2.length()) return false;
    int[] need = new int[26];
    int[] window = new int[26];
    for (int i = 0; i < len; i++) {
        need[s1.charAt(i) - 'a']++;
        window[s2.charAt(i) - 'a']++;
    }
    int matches = 0;
    for (int x = 0; x < 26; x++) {
        if (window[x] == need[x]) matches++;
    }
    for (int i = len; i < s2.length(); i++) {
        if (matches == 26) return true;
        int in = s2.charAt(i) - 'a';
        int out = s2.charAt(i - len) - 'a';
        window[in]++;
        if (window[in] == need[in]) matches++;
        else if (window[in] == need[in] + 1) matches--;
        window[out]--;
        if (window[out] == need[out]) matches++;
        else if (window[out] == need[out] - 1) matches--;
    }
    return matches == 26;
}

