def checkInclusion(self, s1: str, s2: str) -> bool:
    length = len(s1)
    if length > len(s2):
        return False
    need = [0] * 26
    window = [0] * 26
    for i in range(length):
        need[ord(s1[i]) - ord('a')] += 1
        window[ord(s2[i]) - ord('a')] += 1
    matches = sum(1 for x in range(26) if window[x] == need[x])
    for i in range(length, len(s2)):
        if matches == 26:
            return True
        inc = ord(s2[i]) - ord('a')
        dec = ord(s2[i - length]) - ord('a')
        window[inc] += 1
        if window[inc] == need[inc]:
            matches += 1
        elif window[inc] == need[inc] + 1:
            matches -= 1
        window[dec] -= 1
        if window[dec] == need[dec]:
            matches += 1
        elif window[dec] == need[dec] - 1:
            matches -= 1
    return matches == 26

